def queue_step(capacity,state,operation,value=None):
    if type(capacity) is not int or not 1<=capacity<=8:
        raise ValueError("capacity must be 1..8")
    if type(state) is not tuple or len(state)!=2:
        raise ValueError("expected (items,closed) state")
    items,closed=state
    if type(items) is not tuple or len(items)>capacity or type(closed) is not bool:
        raise ValueError("invalid queue state")
    if any(type(x) is not int or not 0<=x<=100 for x in items):
        raise ValueError("invalid queued value")
    if operation=="push":
        if type(value) is not int or not 0<=value<=100:
            raise ValueError("invalid pushed value")
        if closed:return state,"closed",None
        if len(items)==capacity:return state,"full",None
        return (items+(value,),closed),"pushed",None
    if operation not in ("pop","close") or value is not None:
        raise ValueError("invalid operation")
    if operation=="close":return (items,True),"closed",None
    if not items:return state,"drained" if closed else "empty",None
    return (items[1:],closed),"popped",items[0]

state=((),False)
for operation,value in [("push",0),("push",2),("push",3),("close",None),
