#include <array>
#include <condition_variable>
#include <cstddef>
#include <iostream>
#include <mutex>
#include <optional>
#include <thread>

class BoundedRing {
    std::array<int,2> data_{};
    std::size_t head_=0,count_=0;
    bool closed_=false;
    std::mutex mutex_;
    std::condition_variable not_empty_,not_full_;
public:
    bool push(int value) {
        std::unique_lock<std::mutex> lock(mutex_);
        not_full_.wait(lock,[this]{return closed_ || count_<data_.size();});
        if(closed_)return false;
        data_[(head_+count_)%data_.size()]=value;
        ++count_;
        lock.unlock();
        not_empty_.notify_one();
        return true;
    }
    std::optional<int> pop() {
        std::unique_lock<std::mutex> lock(mutex_);
        not_empty_.wait(lock,[this]{return closed_ || count_>0;});
        if(count_==0)return std::nullopt;
        const int value=data_[head_];
        head_=(head_+1)%data_.size();
        --count_;
        lock.unlock();
        not_full_.notify_one();
        return value;
    }
    void close() {
        { std::lock_guard<std::mutex> lock(mutex_); closed_=true; }
        not_empty_.notify_all();
        not_full_.notify_all();
    }
};
struct CloseOnExit {
    BoundedRing& queue;
    ~CloseOnExit(){queue.close();}
};

int main() {
    BoundedRing queue;
    std::array<int,6> received{};
    std::size_t count=0;
    bool overflow=false;
    {
        std::jthread consumer([&] {
            while(const auto item=queue.pop()) {
                if(count<received.size())received[count]=*item;
                else overflow=true;
                ++count;
            }
        });
        CloseOnExit closer{queue}; // closes before consumer's joining destructor
        for(int value=0;value<6;++value)
            if(!queue.push(value))return 2;
        queue.close(); // idempotent; remaining accepted items still drain
    }
    int sum=0;
    bool ordered=!overflow && count==received.size();
    for(std::size_t i=0;i<received.size();++i) {
        sum+=received[i];
        if(received[i]!=static_cast<int>(i))ordered=false;
    }
    std::cout<<std::boolalpha<<count<<' '<<sum<<' '<<ordered<<'\n';
    std::cout<<queue.push(99)<<' '<<(!queue.pop().has_value())<<'\n';
}
